const unique = Array.from(new Set(Array.from(SOURCE).filter(char => /\p{Script=Han}/u.test(char))));

export const HSK500_CHARACTERS = unique.slice(0, 500);

export function getCharacterAt(index: number): string {
  if (!Number.isInteger(index) || index < 0 || index >= HSK500_CHARACTERS.length) {
    throw new RangeError(`Character index must be between 0 and ${HSK500_CHARACTERS.length - 1}`);
  }
  return HSK500_CHARACTERS[index];
}
